/* Critical navigation handler: register before the rest of the app initializes. */
document.addEventListener('click', function(event) {
  const control = event.target instanceof Element ? event.target.closest('[data-page]') : null;
  if (!control) return;
  const targetId = 'page-' + control.getAttribute('data-page');
  const page = document.getElementById(targetId);
  if (!page) return;
  event.preventDefault();
  document.querySelectorAll('.page').forEach(node => node.classList.toggle('active', node === page));
  document.querySelectorAll('[data-page]').forEach(node => node.classList.toggle('active', node === control || node.getAttribute('data-page') === control.getAttribute('data-page')));
  window.scrollTo(0, 0);
}, true);
