let activeChatId = null;
function ensureChat(){
  state.sessions = Array.isArray(state.sessions) ? state.sessions : [];
  let chat = state.sessions.find(x=>x.id===activeChatId);
  if(!chat){chat={id:String(Date.now()),title:'New conversation',updated:Date.now(),messages:[]};state.sessions.unshift(chat);activeChatId=chat.id;save();}
  return chat;
}
function renderChatMessages(){
  const chat=ensureChat(), box=$('#chatMessages');box.innerHTML='';
  if(!chat.messages.length){addMessage(tr('tutorWelcome'),'tutor');return;}
  chat.messages.forEach(m=>addMessage(m.content,m.role==='user'?'user':'tutor',false));
  box.scrollTop=box.scrollHeight;
}
function renderHistory(){
  state.sessions=Array.isArray(state.sessions)?state.sessions:[];
  $('#historyCount').textContent=state.sessions.length;
  const list=$('#chatHistoryList');list.innerHTML='';
  if(!state.sessions.length){const p=document.createElement('p');p.className='muted';p.textContent='Your saved conversations appear here.';list.append(p);return;}
  state.sessions.slice(0,15).forEach(c=>{const b=document.createElement('button');b.className='history-item'+(c.id===activeChatId?' active':'');const title=document.createElement('b');title.textContent=c.title||'Conversation';const small=document.createElement('small');small.textContent=new Date(c.updated).toLocaleString();b.append(title,small);b.onclick=()=>{activeChatId=c.id;renderHistory();renderChatMessages()};list.append(b)});
}
function addMessage(text,type,actions=true){let wrap=document.createElement('div');wrap.className='message '+(type==='user'?'user-message':'tutor-message');let av=document.createElement('div');av.className='message-avatar';av.textContent=type==='user'?'L':'✳';let bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=text;wrap.append(av,bubble);$('#chatMessages').append(wrap);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;return bubble}
function showWordSuggestions(items){const box=$('#suggestedWords');box.innerHTML='';if(!items?.length){box.hidden=true;return;}items.forEach(item=>{if(!item.word||!item.meaning)return;const b=document.createElement('button');b.className='word-suggestion';const strong=document.createElement('b');strong.textContent=item.word;const small=document.createElement('small');small.textContent=item.meaning;const add=document.createElement('span');add.textContent='+ Save';b.append(strong,small,add);b.onclick=()=>{if(state.words.some(w=>w.word.toLowerCase()===item.word.toLowerCase())){toast('Already in your vocabulary');return;}state.words.unshift({id:Date.now()+Math.random(),word:item.word,meaning:item.meaning,example:item.example||'',mastered:false});save();renderWords();toast(tr('wordAdded'));b.disabled=true;add.textContent='✓ Saved';};box.append(b)});box.hidden=!box.children.length;}
