function offlineTutorReply(userText){
  const bank=offlinePhrases[state.learning]||offlinePhrases.Spanish;
  const text=userText.toLowerCase();
  let index=0;
  if(/cafe|coffee|food|restaurant|comer|café|еда|кафе|заказ|restaurant|food/.test(text))index=2;
  else if(/price|cost|cuesta|сто|сколько|precio/.test(text))index=3;
  else if(/understand|repeat|повтор|понима|no entiendo/.test(text))index=4;
  else if(/name|introduc|меня зовут|present|llamo/.test(text))index=1;
  else if(/learn|study|учу|изуч|aprender|estudi/.test(text))index=5;
  else if(/hello|hola|привет|здравств|bonjour|ciao/.test(text))index=0;
  const item=bank[index];
  const intro=state.ui==='ru'?'Давай потренируем полезную фразу:':state.ui==='es'?'Vamos a practicar una frase útil:':'Let’s practise a useful phrase:';
  const prompt=state.ui==='ru'?'Попробуй написать свой вариант на '+state.learning+'.':state.ui==='es'?'Intenta escribir tu propia versión en '+state.learning+'.':'Try writing your own version in '+state.learning+'.';
  return intro+'\n\n'+item[0]+'\n'+item[1]+'\n\n'+(state.ui==='ru'?'Пример: ':state.ui==='es'?'Ejemplo: ':'Example: ')+item[2]+'\n\n'+prompt;
}
async function sendChat(text){
  text=text.trim();if(!text)return;
  const chat=ensureChat();chat.messages.push({role:'user',content:text});chat.updated=Date.now();
  if(chat.title==='New conversation')chat.title=text.slice(0,42)+(text.length>42?'…':'');
  addMessage(text,'user');$('#chatInput').value='';$('#suggestedWords').hidden=true;
  state.sentences+=(text.match(/[.!?。！？]/g)||[]).length;$('#sentenceCount').textContent=Math.min(5,state.sentences)+' / 5 sentences';$('#sentenceProgress').style.width=Math.min(100,state.sentences/5*100)+'%';
  const status=$('#chatStatus'), input=$('#chatInput'), send=$('.send-btn');status.textContent=tr('thinking');input.disabled=true;send.disabled=true;
  await new Promise(resolve=>setTimeout(resolve,180));
  const reply=offlineTutorReply(text);
  chat.messages.push({role:'assistant',content:reply});chat.updated=Date.now();addMessage(reply,'tutor');
  const bank=offlinePhrases[state.learning]||offlinePhrases.Spanish;
  const suggestion=bank[Math.floor(Math.random()*bank.length)];
  showWordSuggestions([{word:suggestion[0],meaning:suggestion[1],example:suggestion[2]}]);
  status.textContent=state.ui==='ru'?'Офлайн-практика · без API':state.ui==='es'?'Práctica sin conexión · sin API':'Offline practice · no API required';
  input.disabled=false;send.disabled=false;input.focus();
  state.minutes=(state.minutes||0)+1;const now=new Date(),key=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');state.activity[key]=(state.activity[key]||0)+1;save();renderStats();renderHistory();
}
